/**
 * Parser de LinkedIn Job Alert Digest — para n8n Code node
 * Extrae titulo, url (limpia), empleador, ubicacion, categoria
 * de emails multipart/alternative con text/plain en quoted-printable.
 * 
 * Probado con 11/11 pegas de 3 emails reales (Julio 2026).
 * v1.1: detección de sueldo/rango salarial en título y descripción.
 */

const items = $input.all();
const output = [];

// --- Quoted-printable decoder con soporte UTF-8 multi-byte ---
// El campo `text` que entrega el Gmail Trigger (con simple:false) ya viene
// decodificado -- no es quoted-printable real. Confirmado con datos reales:
// los pocos "=XX" sueltos que aparecen son coincidencia de query strings en
// URLs (p.ej. "trackingId=72BF...", "geoId=104621616"), no bytes
// codificados. La version anterior de este decoder reinterpretaba TODO el
// texto como bytes crudos (via charCodeAt), así que cualquier tilde ya
// presente en el texto (é, ú, ñ) se corrompía en U+FFFD al pasar por
// TextDecoder.
//
// Por eso ahora solo se decodifican RACHAS de 2+ "=XX" consecutivos --
// eso es lo que produce un caracter UTF-8 multi-byte real (p.ej. =C3=A9).
// Un "=XX" aislado se deja como texto literal, y cualquier caracter que no
// sea parte de una racha pasa intacto, sin reinterpretarse como byte.
function decodeQP(str) {
  str = str.replace(/=\r?\n/g, '');
  return str.replace(/(?:=[0-9A-Fa-f]{2}){2,}/g, run => {
    const bytes = [];
    for (let i = 0; i < run.length; i += 3) bytes.push(parseInt(run.substring(i + 1, i + 3), 16));
    try { return new TextDecoder('utf-8', { fatal: false }).decode(new Uint8Array(bytes)); }
    catch (_) { return run; }
  });
}

// --- Categorización ---
function categorizar(t) {
  t = (t || '').toLowerCase();

  // 0. Guarda de avisos que no son de TI. Va PRIMERO porque varios de estos
  // títulos traen palabras que más abajo son señal fuerte de otra cosa:
  // "Social Media & Community *Analyst*" caía en Data y "*Community Manager*"
  // caería en Liderazgo. Lista corta y explícita a propósito — acá un falso
  // positivo saca del listado una pega que sí era válida.
  if (/\bcontent (reviewer|creator|writer)\b|\besl\b|\bteacher\b|\bprofesor|\btutor(ing|ía)?\b|\bredactor|\bcopywriter\b|\bcommunity (manager|analyst)\b|\bsocial media\b|\bappointment setting?\b|\bvideo editor\b|\bshort-form video\b|\bcoletor de dados\b|\bphoto collection\b|\bdeduplication collection\b/i.test(t)) return 'Otros';

  // 1-4. Stack explícito en el título: la señal más confiable que hay, así que
  // va antes que cualquier rol. Se conservan tal cual venían de producción,
  // incluido que \breact\b gane antes que Mobile en "React Native" (cambiarlo
  // movería pegas que hoy están clasificadas como Frontend).
  if (/\bfront.?end\b|frontend|\breact\b|\bvue\b|\bangular\b|\bui.ux\b|\bcss\b|\bhtml\b|\btypescript\b|\bjavascript\b|\bjs\b/i.test(t)) return 'Frontend';

  // Backend ampliado con lenguajes y runtimes de servidor que no estaban y por
  // eso caían en Otros (COBOL/mainframe, Elixir/Phoenix, Scala, C++...).
  // Ojo: acá NO van las plataformas de ecosistema (Shopify, Salesforce, SAP,
  // ServiceNow, Oracle...) — esas tienen su propia regla más abajo, a Otros.
  if (/\bback.?end\b|backend|\bnode\b|\bpython\b|\bdjango\b|\bflask\b|\bfastapi\b|\bgo\b|\bgolang\b|\brust\b|\bjava\b|\bspring\b|\bquarkus\b|\.net\b|\bc#\b|\bc\+\+|\bphp\b|\blaravel\b|\bsymfony\b|\brails\b|\bruby\b|\bnestjs\b|\bcobol\b|\bmainframe\b|\bas.?400\b|\bscala\b|\belixir\b|\bphoenix\b|\berlang\b|\bclojure\b|\bperl\b|\bdelphi\b|\brest api(s)?\b|\bapi(s)? rest\b|\bmicroservici/i.test(t)) return 'Backend';

  if (/\bfull.?stack\b|fullstack/i.test(t)) return 'Full Stack';

  // \binfra\b no matcheaba "Infraestructura" ni "Infrastructure" (no hay borde
  // de palabra dentro de la palabra), así que esos avisos dependían de que la
  // fuente trajera categoría propia y si no se iban a Otros.
  if (/\bdevops\b|\bsre\b|\binfra(estructura|structure)?\b|\bcloud\b|\baws\b|\bazure\b|\bgcp\b|\bkubernetes\b|\bdocker\b|\bterraform\b|\bdeploy(ment)?\b|\bsys.?admin\b/i.test(t)) return 'DevOps';

  // 5. QA. Va antes de AI y de Data/BI —como ya hacían 4 de las 5 copias— para
  // que "Analista QA Funcional" sea QA y no Data por la palabra "analista", y
  // que "Senior QA Engineer (AI Platform Systems)" sea QA y no AI. La excepción
  // por \bdata\b es para el caso inverso: "Data Quality Analyst" es Data/BI,
  // el "quality" ahí califica al dato, no al rol.
  if (/\bqa\b|\bsdet\b|\btester\b|\btesting\b|\bcalidad\b|\bquality\b/i.test(t) && !/\bdata\b/i.test(t)) return 'QA';

  // 6. Soporte. Antes de Data/BI por el mismo motivo que QA: "Analista de
  // Soporte Técnico" y "Analista de Soporte y Monitoreo (NOC)" caían en Data
  // por la palabra "analista". Además, esta regla solo existía en la copia de
  // LinkedIn — las otras cuatro fuentes no podían producir la categoría nunca,
  // y de ahí que "Soporte" tuviera 1 sola pega con 945 publicadas.
  if (/\bsoporte\b|\bsupport\b|\bhelp.?desk\b|\bservice.?desk\b|\bmesa de ayuda\b|\bnoc\b/i.test(t)) return 'Soporte';

  // 6. IA/ML/LLM. Categoría nueva: estos términos vivían dentro de la regla de
  // Data y se llevaban 72 de sus 194 pegas ("AI Engineer", "AI Automation
  // Engineer", "Forward Deployed AI Engineer"), que no son ingeniería de datos.
  // Va antes de Data/BI pero después del stack explícito, para que un
  // "Python ML Engineer" siga siendo Backend igual que hoy.
  if (/\bia\b|\ba\.?i\.?\b|\bml\b|\bmlops\b|\bllm(s)?\b|\bgen.?ai\b|\bnlp\b|\bmachine.?learning\b|\bdeep.?learning\b|\bcomputer vision\b|\binteligencia artificial\b|\bartificial intelligence\b|\bprompt engineer/i.test(t)) return 'AI/ML';

  // 7. Data/BI (antes "Data"). Sin los términos de IA, que subieron a la regla
  // anterior, y con \bbi\b agregado: solo estaba \bpower.bi\b, así que
  // "Senior BI Developer (Tableau)" no matcheaba por "BI".
  if (/\bdata\b|\bdatos\b|\banalis(ta|tas)\b|\banalyst(s)?\b|\banalytics\b|\betl\b|\belt\b|\bbi\b|\bpower.?bi\b|\btableau\b|\blooker\b|\bqlik\b|\bwarehouse\b|\bdbt\b|\bspark\b|\bsnowflake\b|\bdatabricks\b/i.test(t)) return 'Data/BI';

  if (/\bmobile\b|\bm[oó]vil(es)?\b|\bandroid\b|\bios\b|\bswift\b|\bkotlin\b|\bflutter\b|\breact.native\b/i.test(t)) return 'Mobile';

  // \bsecurity\b no matcheaba "cybersecurity" por el mismo motivo que \binfra\b:
  // "Cybersecurity Lead" terminaba en Liderazgo y "Senior Cybersecurity
  // Specialist" en Otros.
  if (/\bsecurity\b|\bcyber|\bciber|\bseguridad\b|\bpentest|\bethical hack|\bdevsecops\b|\binfosec\b|\bappsec\b|\bsoc\b/i.test(t)) return 'Ciberseguridad';

  // 8. Diseño va ANTES de Liderazgo: "Líder UX/UI", "UX Design Lead" y
  // "UX Design Manager" son pegas de diseño con un modificador de rol, no
  // pegas de liderazgo. (La copia de LinkedIn las mandaba a Gestión.)
  if (/\bdiseñ|\bdesign(er)?\b|\bart director\b|\bux\b|\bui\b|\bfigma\b|\bsketch\b|\bphotoshop\b|\billustrator\b/i.test(t)) return 'Diseño';

  // 9. Liderazgo (antes "Gestión"), ampliada con arquitecto/CTO/subgerente/VP,
  // que caían en Otros. Va después del stack, de Data/BI y de Diseño a
  // propósito: un "Arquitecto de Datos" o un "Engineering Manager, Data" siguen
  // siendo pegas de datos — el liderazgo es el modificador, no el eje.
  if (/\bproject.manager\b|\bscrum.master\b|\bproduct.manager\b|\bproduct.owner\b|\bagile\b|\bjefe\b|\bgerente\b|\bsub.?gerente\b|\bl[ií]der\b|\blead\b|\btech.?lead\b|\bmanager\b|\bdirector\b|\bcoordinador\b|\barquitect|\barchitect\b|\bcto\b|\bcio\b|\bciso\b|\bhead of\b|\bvp\b|\bvicepresident/i.test(t)) return 'Liderazgo';

  // 11. Plataformas de ecosistema. Van ANTES de la regla de dev genérico
  // porque si no "Shopify Developer" o "Consultor/a SAP" se colarían a
  // Full Stack por la palabra "developer"/"desarrollador".
  if (/\bshopify\b|\bsalesforce\b|\bsap\b|\babap\b|\bservicenow\b|\bodoo\b|\bmagento\b|\bwordpress\b|\bdrupal\b|\bsharepoint\b|\bdynamics\b|\bsiebel\b|\bpeoplesoft\b|\boracle\b/i.test(t)) return 'Otros';

  // 12. Dev genérico sin stack en el título ("Software Engineer",
  // "Desarrollador/a Senior", "Programador/a"): era el 70% de Otros. Va al
  // final justo por eso — solo agarra lo que ninguna regla más específica
  // reclamó. "Ingeniero" a secas NO entra: en el corpus hay "Ingeniero Civil
  // Industrial" y "Ingeniero de Estudios Actuariales", que no son pegas dev.
  if (/\bsoftware engineer\b|\bsoftware develop|\bingenier[oa]?(?:\/a|\(a\))?\s+(?:de\s+|en\s+)?software\b|\bingenier[ií]a de software\b|\bdesarrollador|\bdesarrolladora|\bdesarrollo de software\b|\bdeveloper\b|\bprogramador|\bprogramadora|\bweb develop/i.test(t)) return 'Full Stack';

  return 'Otros';
}

// --- Badge patterns (se colocan donde iría la empresa) ---
// Insignias que LinkedIn intercala entre la ubicacion y el "View job:".
// Se toleran sufijos (el texto real es "Apply with resume & profile", que con
// el anclaje de fin anterior nunca matcheaba) y variantes con numero
// ("1 connection", "77 school alumni"). "school alum" (sin "ni") se ve en
// producción -- el propio texto plano de LinkedIn a veces trunca la palabra.
const BADGE_RE = /^(\d+\+?\s+(connections?|school alum(?:ni)?|alumni|applicants?)|this company is actively hiring|actively hiring|actively reviewing applicants|apply with resume.*|easy apply|be an early applicant|promoted|viewed|no longer accepting.*)$/i;

// Lineas de encabezado/seccion del email: nunca son el titulo de un aviso.
// Sirven de red de seguridad: si LinkedIn agrega una insignia nueva que
// BADGE_RE no conozca, el bloque se descarta en vez de guardarse corrido.
const NO_ES_TITULO_RE = /^(your job alert|\d+\+?\s+new jobs match|new jobs match|jobs similar to|results from the new|view all jobs|see all jobs|stand out|this email was|you are receiving|manage your|unsubscribe|learn why|help:)/i;

// --- Detección de sueldo/rango salarial ---
function extraerSueldo(texto) {
  if (!texto) return null;
  // Pesos chilenos: $1.500.000, $1500000, CLP 1.500.000, CLP$1.5M
  let m = texto.match(/(?:CLP\s*)?\$\s*[\d.,]+\s*(?:[.-]\s*(?:CLP\s*)?\$\s*[\d.,]+)?\s*(?:CLP|clp|pesos|l[ií]quido|bruto|liquido)?/i);
  if (m) return m[0].trim();
  // UF
  m = texto.match(/UF\s*[\d.,]+/i);
  if (m) return m[0].trim();
  // USD / dólares
  m = texto.match(/(?:USD|usd|U\$)\s*[\d.,]+/i);
  if (m) return m[0].trim();
  // Renta/Sueldo/Salario: $X
  m = texto.match(/(?:renta|sueldo|salario|remuneraci[oó]n)\s*:?\s*(?:hasta|desde|entre)?\s*(?:CLP\s*)?\$?\s*[\d.,]+\s*(?:[.-]\s*(?:CLP\s*)?\$?\s*[\d.,]+)?\s*(?:CLP|clp|pesos|l[ií]quido|bruto)?/i);
  if (m) return m[0].trim();
  return null;
}

// --- Detección de tags (remote, etc) ---
function detectarTags(titulo, ubicacion, lines) {
  const tags = [];
  const texto = [titulo, ubicacion, ...lines.slice(0, 6)].join(' ').toLowerCase();
  if (/\bremote\b|\bremoto\b|\bteletrabajo\b|\bhome.?office\b|\bwork.?from.?home\b|\b100%?\s*remoto\b|\btrabajo\s*remoto\b|\bmodalidad\s*remot[ao]\b/i.test(texto)) {
    tags.push('remote');
  }
  return tags.length > 0 ? tags.join(',') : null;
}

// --- Procesar cada email ---
for (const item of items) {
  // Con el Gmail Trigger en modo "simple: false" el campo real es `text`
  // (y `html` de respaldo) -- `textPlain`/`body` se dejan como fallback
  // por si alguna vez cambia el modo del nodo.
  let body = item.json.text || item.json.textPlain || item.json.body || item.json.html || '';
  if (typeof body === 'object' && body.content) body = body.content;
  if (!body || body.length < 20) continue;

  body = decodeQP(body);
  const blocks = body.split(/\n\s*-{15,}\s*\n/);

  for (let bi = 0; bi < blocks.length; bi++) {
    const lines = blocks[bi].trim().split('\n').map(l => l.trim()).filter(l => l.length > 0);
    if (lines.length < 4) continue;

    // Un aviso real SIEMPRE termina en "View job: <url>", precedido por
    // titulo / empresa / ubicacion. Antes se leia el bloque desde arriba y se
    // saltaban los encabezados por patron, pero cada variante nueva del email
    // ("28 new jobs match your preferences.", "Results from the new AI-powered
    // job search", "View all jobs: ...") se colaba como si fuera una pega, y
    // encima se robaba la URL del aviso real que venia abajo.
    //
    // Anclando en "View job:" y leyendo hacia arriba, todo lo que este por
    // encima del aviso es irrelevante por construccion: no hay lista de
    // encabezados que mantener.
    for (let i = 0; i < lines.length; i++) {
      if (!/^view job:\s*/i.test(lines[i])) continue;

      const url = lines[i].replace(/^view job:\s*/i, '').trim();
      if (!url) continue;

      // Hacia arriba: descartar badges y lineas con URL (son links de seccion,
      // tipo "View all jobs: ..."), hasta juntar ubicacion, empresa y titulo.
      const campos = [];
      for (let j = i - 1; j >= 0 && campos.length < 3; j--) {
        const l = lines[j];
        if (/^view job:\s*/i.test(l)) break;   // llegamos al aviso anterior
        if (BADGE_RE.test(l)) continue;
        if (/https?:\/\//i.test(l)) continue;
        campos.push(l);
      }
      if (campos.length < 3) continue;

      const [ubicacion, empleador, titulo] = campos;
      // Si alguno de los tres huele a encabezado, el bloque quedo corrido
      // (insignia desconocida). Mejor descartarlo que guardar basura.
      if (!titulo || [titulo, empleador, ubicacion].some(c => NO_ES_TITULO_RE.test(c))) continue;

      const jid = url.match(/\/jobs\/view\/(\d+)/);
      const urlLimpia = jid ? `https://www.linkedin.com/jobs/view/${jid[1]}/` : url.split('?')[0];

      const contexto = [titulo, empleador, ubicacion].join(' ');
      output.push({
        json: {
          titulo,
          url: urlLimpia,
          empleador: empleador || 'No especificado',
          ubicacion: ubicacion || 'Chile',
          sueldo: extraerSueldo(contexto),
          descripcion: `${titulo} en ${empleador || 'empresa'}${ubicacion ? ', ' + ubicacion : ''}`,
          categoria: categorizar(titulo),
          tags: detectarTags(titulo, ubicacion, lines),
          fuente: 'linkedin',
          email_origen: item.json.to || item.json.To || '',
          fecha_publicacion: new Date().toISOString()
        }
      });
    }
  }
}

return output;

// Categorías de GetOnBoard relevantes para developers/tech + diseño.
// API pública v0, sin autenticación: https://www.getonbrd.com/api/v0/categories
const CATEGORIAS = [
  'programming',
  'mobile-developer',
  'sysadmin-devops-qa',
  'data-science-analytics',
  'machine-learning-ai',
  'cybersecurity',
  'design-ux'
];
return CATEGORIAS.map(category => ({ json: { category } }));

// Normaliza jobs de GetOnBoard (API pública v0, sin auth) al esquema de "pegas".
// Filtra a Chile o remoto: GetOnBoard es una plataforma LatAm, así que su tag
// "Remote" es mayormente remoto-LatAm-friendly (a diferencia de RemoteOK/WWR,
// que son globales/US-centric y no se incluyeron por eso).
const items = $input.all();

function categorizar(t) {
  t = (t || '').toLowerCase();

  // 0. Guarda de avisos que no son de TI. Va PRIMERO porque varios de estos
  // títulos traen palabras que más abajo son señal fuerte de otra cosa:
  // "Social Media & Community *Analyst*" caía en Data y "*Community Manager*"
  // caería en Liderazgo. Lista corta y explícita a propósito — acá un falso
  // positivo saca del listado una pega que sí era válida.
  if (/\bcontent (reviewer|creator|writer)\b|\besl\b|\bteacher\b|\bprofesor|\btutor(ing|ía)?\b|\bredactor|\bcopywriter\b|\bcommunity (manager|analyst)\b|\bsocial media\b|\bappointment setting?\b|\bvideo editor\b|\bshort-form video\b|\bcoletor de dados\b|\bphoto collection\b|\bdeduplication collection\b/i.test(t)) return 'Otros';

  // 1-4. Stack explícito en el título: la señal más confiable que hay, así que
  // va antes que cualquier rol. Se conservan tal cual venían de producción,
  // incluido que \breact\b gane antes que Mobile en "React Native" (cambiarlo
  // movería pegas que hoy están clasificadas como Frontend).
  if (/\bfront.?end\b|frontend|\breact\b|\bvue\b|\bangular\b|\bui.ux\b|\bcss\b|\bhtml\b|\btypescript\b|\bjavascript\b|\bjs\b/i.test(t)) return 'Frontend';

  // Backend ampliado con lenguajes y runtimes de servidor que no estaban y por
  // eso caían en Otros (COBOL/mainframe, Elixir/Phoenix, Scala, C++...).
  // Ojo: acá NO van las plataformas de ecosistema (Shopify, Salesforce, SAP,
  // ServiceNow, Oracle...) — esas tienen su propia regla más abajo, a Otros.
  if (/\bback.?end\b|backend|\bnode\b|\bpython\b|\bdjango\b|\bflask\b|\bfastapi\b|\bgo\b|\bgolang\b|\brust\b|\bjava\b|\bspring\b|\bquarkus\b|\.net\b|\bc#\b|\bc\+\+|\bphp\b|\blaravel\b|\bsymfony\b|\brails\b|\bruby\b|\bnestjs\b|\bcobol\b|\bmainframe\b|\bas.?400\b|\bscala\b|\belixir\b|\bphoenix\b|\berlang\b|\bclojure\b|\bperl\b|\bdelphi\b|\brest api(s)?\b|\bapi(s)? rest\b|\bmicroservici/i.test(t)) return 'Backend';

  if (/\bfull.?stack\b|fullstack/i.test(t)) return 'Full Stack';

  // \binfra\b no matcheaba "Infraestructura" ni "Infrastructure" (no hay borde
  // de palabra dentro de la palabra), así que esos avisos dependían de que la
  // fuente trajera categoría propia y si no se iban a Otros.
  if (/\bdevops\b|\bsre\b|\binfra(estructura|structure)?\b|\bcloud\b|\baws\b|\bazure\b|\bgcp\b|\bkubernetes\b|\bdocker\b|\bterraform\b|\bdeploy(ment)?\b|\bsys.?admin\b/i.test(t)) return 'DevOps';

  // 5. QA. Va antes de AI y de Data/BI —como ya hacían 4 de las 5 copias— para
  // que "Analista QA Funcional" sea QA y no Data por la palabra "analista", y
  // que "Senior QA Engineer (AI Platform Systems)" sea QA y no AI. La excepción
  // por \bdata\b es para el caso inverso: "Data Quality Analyst" es Data/BI,
  // el "quality" ahí califica al dato, no al rol.
  if (/\bqa\b|\bsdet\b|\btester\b|\btesting\b|\bcalidad\b|\bquality\b/i.test(t) && !/\bdata\b/i.test(t)) return 'QA';

  // 6. Soporte. Antes de Data/BI por el mismo motivo que QA: "Analista de
  // Soporte Técnico" y "Analista de Soporte y Monitoreo (NOC)" caían en Data
  // por la palabra "analista". Además, esta regla solo existía en la copia de
  // LinkedIn — las otras cuatro fuentes no podían producir la categoría nunca,
  // y de ahí que "Soporte" tuviera 1 sola pega con 945 publicadas.
  if (/\bsoporte\b|\bsupport\b|\bhelp.?desk\b|\bservice.?desk\b|\bmesa de ayuda\b|\bnoc\b/i.test(t)) return 'Soporte';

  // 6. IA/ML/LLM. Categoría nueva: estos términos vivían dentro de la regla de
  // Data y se llevaban 72 de sus 194 pegas ("AI Engineer", "AI Automation
  // Engineer", "Forward Deployed AI Engineer"), que no son ingeniería de datos.
  // Va antes de Data/BI pero después del stack explícito, para que un
  // "Python ML Engineer" siga siendo Backend igual que hoy.
  if (/\bia\b|\ba\.?i\.?\b|\bml\b|\bmlops\b|\bllm(s)?\b|\bgen.?ai\b|\bnlp\b|\bmachine.?learning\b|\bdeep.?learning\b|\bcomputer vision\b|\binteligencia artificial\b|\bartificial intelligence\b|\bprompt engineer/i.test(t)) return 'AI/ML';

  // 7. Data/BI (antes "Data"). Sin los términos de IA, que subieron a la regla
  // anterior, y con \bbi\b agregado: solo estaba \bpower.bi\b, así que
  // "Senior BI Developer (Tableau)" no matcheaba por "BI".
  if (/\bdata\b|\bdatos\b|\banalis(ta|tas)\b|\banalyst(s)?\b|\banalytics\b|\betl\b|\belt\b|\bbi\b|\bpower.?bi\b|\btableau\b|\blooker\b|\bqlik\b|\bwarehouse\b|\bdbt\b|\bspark\b|\bsnowflake\b|\bdatabricks\b/i.test(t)) return 'Data/BI';

  if (/\bmobile\b|\bm[oó]vil(es)?\b|\bandroid\b|\bios\b|\bswift\b|\bkotlin\b|\bflutter\b|\breact.native\b/i.test(t)) return 'Mobile';

  // \bsecurity\b no matcheaba "cybersecurity" por el mismo motivo que \binfra\b:
  // "Cybersecurity Lead" terminaba en Liderazgo y "Senior Cybersecurity
  // Specialist" en Otros.
  if (/\bsecurity\b|\bcyber|\bciber|\bseguridad\b|\bpentest|\bethical hack|\bdevsecops\b|\binfosec\b|\bappsec\b|\bsoc\b/i.test(t)) return 'Ciberseguridad';

  // 8. Diseño va ANTES de Liderazgo: "Líder UX/UI", "UX Design Lead" y
  // "UX Design Manager" son pegas de diseño con un modificador de rol, no
  // pegas de liderazgo. (La copia de LinkedIn las mandaba a Gestión.)
  if (/\bdiseñ|\bdesign(er)?\b|\bart director\b|\bux\b|\bui\b|\bfigma\b|\bsketch\b|\bphotoshop\b|\billustrator\b/i.test(t)) return 'Diseño';

  // 9. Liderazgo (antes "Gestión"), ampliada con arquitecto/CTO/subgerente/VP,
  // que caían en Otros. Va después del stack, de Data/BI y de Diseño a
  // propósito: un "Arquitecto de Datos" o un "Engineering Manager, Data" siguen
  // siendo pegas de datos — el liderazgo es el modificador, no el eje.
  if (/\bproject.manager\b|\bscrum.master\b|\bproduct.manager\b|\bproduct.owner\b|\bagile\b|\bjefe\b|\bgerente\b|\bsub.?gerente\b|\bl[ií]der\b|\blead\b|\btech.?lead\b|\bmanager\b|\bdirector\b|\bcoordinador\b|\barquitect|\barchitect\b|\bcto\b|\bcio\b|\bciso\b|\bhead of\b|\bvp\b|\bvicepresident/i.test(t)) return 'Liderazgo';

  // 11. Plataformas de ecosistema. Van ANTES de la regla de dev genérico
  // porque si no "Shopify Developer" o "Consultor/a SAP" se colarían a
  // Full Stack por la palabra "developer"/"desarrollador".
  if (/\bshopify\b|\bsalesforce\b|\bsap\b|\babap\b|\bservicenow\b|\bodoo\b|\bmagento\b|\bwordpress\b|\bdrupal\b|\bsharepoint\b|\bdynamics\b|\bsiebel\b|\bpeoplesoft\b|\boracle\b/i.test(t)) return 'Otros';

  // 12. Dev genérico sin stack en el título ("Software Engineer",
  // "Desarrollador/a Senior", "Programador/a"): era el 70% de Otros. Va al
  // final justo por eso — solo agarra lo que ninguna regla más específica
  // reclamó. "Ingeniero" a secas NO entra: en el corpus hay "Ingeniero Civil
  // Industrial" y "Ingeniero de Estudios Actuariales", que no son pegas dev.
  if (/\bsoftware engineer\b|\bsoftware develop|\bingenier[oa]?(?:\/a|\(a\))?\s+(?:de\s+|en\s+)?software\b|\bingenier[ií]a de software\b|\bdesarrollador|\bdesarrolladora|\bdesarrollo de software\b|\bdeveloper\b|\bprogramador|\bprogramadora|\bweb develop/i.test(t)) return 'Full Stack';

  return 'Otros';
}

const CATEGORIA_FALLBACK = {
  'Mobile Developer': 'Mobile',
  'SysAdmin / DevOps / QA': 'DevOps',
  'Data Science / Analytics': 'Data/BI',
  'Machine Learning & AI': 'AI/ML',
  'Programming': 'Full Stack',
  'Cybersecurity': 'Ciberseguridad',
  'Design / UX': 'Diseño'
};

const vistos = new Set();
const output = [];

for (const item of items) {
  const body = item.json;
  const jobs = (body && body.data) || [];

  for (const job of jobs) {
    const id = job.id;
    if (!id || vistos.has(id)) continue;
    vistos.add(id);

    const a = job.attributes || {};
    const countries = a.countries || [];
    const esChile = countries.includes('Chile');
    const esRemoto = a.remote === true || countries.includes('Remote');
    if (!esChile && !esRemoto) continue;

    const titulo = a.title || '';
    if (!titulo) continue;

    const catTitulo = categorizar(titulo);
    const categoria = catTitulo !== 'Otros' ? catTitulo : (CATEGORIA_FALLBACK[a.category_name] || 'Otros');
    const ubicacion = esChile ? 'Chile' : (countries[0] || 'Remoto');
    const sueldo = (a.min_salary && a.max_salary) ? `USD ${a.min_salary} - ${a.max_salary} /mes` : null;

    const tags = [];
    if (esRemoto) tags.push('remote');

    output.push({
      json: {
        company_id: (a.company && a.company.data && a.company.data.id) || null,
        titulo,
        url: (job.links && job.links.public_url) || `https://www.getonbrd.com/jobs/${id}`,
        ubicacion,
        categoria,
        sueldo,
        tags: tags.length ? tags.join(',') : null,
        descripcion: `${titulo}${ubicacion ? ', ' + ubicacion : ''}`,
        fuente: 'getonbrd',
        email_origen: null,
        fecha_publicacion: a.published_at ? new Date(a.published_at * 1000).toISOString() : new Date().toISOString()
      }
    });
  }
}

return output;

// IDs de empresa únicos, para resolver el nombre con una sola llamada por empresa
// (en vez de una por cada pega).
const items = $input.all();
const ids = new Set();
for (const item of items) {
  if (item.json.company_id) ids.add(item.json.company_id);
}
return Array.from(ids).map(company_id => ({ json: { company_id } }));

// Combina el nombre real de la empresa (paso anterior) con las pegas ya
// filtradas/normalizadas ("GetOnBoard: filtrar + normalizar") y deja el
// resultado listo para el mismo INSERT que usa LinkedIn.
// OJO: la respuesta de /companies/{id} devuelve data.id como SLUG (ej. "tcit"),
// no el ID numérico que se pidió -- por eso el match es posicional, no por key.
const companies = $input.all();
const companyIds = $('GetOnBoard: IDs de empresa únicas').all().map(i => i.json.company_id);
const nombrePorId = {};
companies.forEach((c, idx) => {
  const data = c.json && c.json.data;
  if (data) nombrePorId[companyIds[idx]] = (data.attributes && data.attributes.name) || null;
});

const pegas = $('GetOnBoard: filtrar + normalizar').all();
return pegas.map(p => {
  const json = { ...p.json };
  json.empleador = (json.company_id && nombrePorId[json.company_id]) || 'No especificado';
  delete json.company_id;
  return { json };
});

// Digest 2x/dia: resume las pegas nuevas desde el ultimo aviso.
//
// El canal ve solo el resumen (conteo por categoria + una linea de stats) y
// el detalle pega por pega se publica como respuesta en el hilo. Antes se
// listaban 3 pegas con detalle en el propio mensaje, pero con una mediana de
// ~24 pegas por envio eso mostraba una muestra arbitraria (y ademas las mas
// viejas del lote, por el ORDER BY ASC de la query); listarlas todas en el
// canal inundaria #trabajos dos veces al dia. El hilo resuelve las dos cosas.
//
// Todo link del mensaje apunta a pegas.devschile.cl (a la pega, a la categoria
// o al home), nunca al aviso original: el objetivo del digest es llevar
// trafico al sitio, y la pagina de la pega ya ofrece el link para postular.
//
// Salida: { text } para el mensaje del canal y { hilo } con los bloques de la
// respuesta -- los arma "Armar hilo de detalle", que necesita el ts que
// devuelve el nodo de Slack y por eso corre despues.
//
// OJO: el nodo Postgres de n8n, cuando el SELECT no encuentra filas, igual
// emite 1 item falso {success:true} en vez de un array vacio. Por eso
// filtramos por la presencia de "titulo", no por items.length.
const items = $input.all().filter(item => item.json && item.json.titulo).map(i => i.json);
if (items.length === 0) return [];

const total = items.length;
const esUno = total === 1;
const pegas = esUno ? 'pega nueva' : 'pegas nuevas';

const aperturas = esUno
  ? [`Hay *1* ${pegas}`, `Llegó *1* ${pegas}`, `Se sumó *1* ${pegas}`,
     `Cayó *1* ${pegas}`, `Tenemos *1* ${pegas}`, `Apareció *1* ${pegas}`,
     `*1* ${pegas} en la vitrina`]
  : [`Hay *${total}* ${pegas}`, `Llegaron *${total}* ${pegas}`, `Se sumaron *${total}* ${pegas}`,
     `Cayeron *${total}* ${pegas}`, `Tenemos *${total}* ${pegas}`, `Aparecieron *${total}* ${pegas}`,
     `*${total}* ${pegas} en la vitrina`];

const cierres = esUno
  ? ['Mírala en pegas.devschile.cl', 'Revísala en pegas.devschile.cl',
     'Échale un ojo en pegas.devschile.cl', 'Está en pegas.devschile.cl',
     'Pásate por pegas.devschile.cl']
  : ['Míralas todas en pegas.devschile.cl', 'Revísalas en pegas.devschile.cl',
     'Échales un ojo en pegas.devschile.cl', 'Están todas en pegas.devschile.cl',
     'El listado completo en pegas.devschile.cl', 'Pásate por pegas.devschile.cl'];

const azar = arr => arr[Math.floor(Math.random() * arr.length)];

/**
 * Titulos, empleadores y sueldos vienen de LinkedIn y GetOnBoard sin ninguna
 * validacion, y en el hilo se interpolan dentro del mrkdwn de Slack. Sin
 * escapar, un aviso titulado `<https://phishing.cl|Postula aquí>` se
 * publicaria en #trabajos como un link de verdad, con el nombre que el
 * atacante quiera. Es el escape que pide la propia documentacion de Slack, y
 * el & va primero o si no se re-escapan los otros dos.
 */
const escapar = t => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

/**
 * Los links del digest apuntan al sitio, NO al aviso original: la gracia es
 * llevar trafico a pegas.devschile.cl, que ademas muestra la pega con su
 * categoria, reacciones y el boton para postular en la fuente. El link a
 * LinkedIn/GetOnBoard sigue estando, a un click, en la propia pagina.
 *
 * Como el destino lo construimos nosotros, ya no hay que validar una url de
 * terceros: se arma con el id (entero de la BD) y un slug que por definicion
 * solo tiene [a-z0-9-]. Un titulo hostil no puede colarse en el destino.
 */
const SITIO = 'https://pegas.devschile.cl';

/** Para separar en PostHog las visitas que llegan del digest. */
const utm = contenido => `?utm_source=slack&utm_medium=digest&utm_content=${contenido}`;

/** Mismo criterio que slugify() en web/app/utils/slug.ts. */
const slugify = texto => String(texto)
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '');

/**
 * `/pega/123-titulo-en-empresa`. El id manda y el resto del slug es solo
 * legibilidad: la pagina lo resuelve con idFromSlug(), asi que el link no se
 * rompe aunque el titulo cambie despues. Sin id no hay link posible -- no
 * deberia pasar nunca, id es la PK.
 */
function linkPega(p) {
  const id = Number(p.id);
  if (!Number.isInteger(id) || id <= 0) return null;
  // El slug se recorta: nadie lo ve (el texto visible es el titulo) y cada
  // link se lleva el presupuesto de caracteres del mensaje. La pagina lo
  // resuelve igual, solo mira el numero.
  const slug = slugify(`${p.titulo || ''} ${empleadorDe(p) || ''}`).slice(0, 40).replace(/-+$/, '');
  return `${SITIO}/pega/${id}${slug ? '-' + slug : ''}${utm('pega')}`;
}

const truncar = (t, n) => (t.length <= n ? t : t.slice(0, n - 1).trimEnd() + '…');

/** GetOnBoard manda "No especificado" cuando no logra resolver la empresa. */
function empleadorDe(p) {
  const e = String(p.empleador || '').trim();
  return !e || /^no especificad[oa]$/i.test(e) ? null : e;
}

const esRemota = p => /remot/i.test(String(p.ubicacion || ''));

/**
 * La ubicacion llega de cinco fuentes y sin normalizar: "Santiago",
 * "Santiago Metropolitan Region, Chile", "Santiago Metropolitan Area",
 * "Provincia de Santiago", "Remote", "Remoto". Se colapsa a algo que quepa
 * en una linea y no repita lo mismo escrito de seis formas.
 */
function ubicacionDe(p) {
  const u = String(p.ubicacion || '').trim();
  if (!u) return null;
  if (esRemota(p)) return 'Remoto';
  if (/santiago/i.test(u)) return 'Santiago';
  return truncar(u.split(',')[0].trim(), 24);
}

function lineaDe(p) {
  const titulo = escapar(truncar(String(p.titulo).trim(), 70));
  const url = linkPega(p);
  let linea = '• ' + (url ? `<${url}|${titulo}>` : titulo);

  const empleador = empleadorDe(p);
  if (empleador) linea += ` · ${escapar(truncar(empleador, 30))}`;

  const donde = ubicacionDe(p);
  if (donde) linea += ` — ${escapar(donde)}`;

  const sueldo = String(p.sueldo || '').trim();
  if (sueldo) linea += ` · 💰 ${escapar(truncar(sueldo, 28))}`;

  return linea;
}

const conteo = {};
for (const p of items) {
  const cat = p.categoria || 'Otros';
  conteo[cat] = (conteo[cat] || 0) + 1;
}
const filas = Object.entries(conteo).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));

const ancho = Math.max(...filas.map(([k]) => k.length));
const maxN = filas[0][1];
// Con una sola categoria la barra siempre saldria llena, asi que no se dibuja.
const conBarras = filas.length > 1;

let msg = `${azar(aperturas)}:\n\n\`\`\`\n`;
for (const [cat, n] of filas) {
  const barra = conBarras ? '  ' + '█'.repeat(Math.max(1, Math.round((n / maxN) * 14))) : '';
  msg += `${cat.padEnd(ancho)} ${String(n).padStart(3)}${barra}\n`;
}
msg += '```\n';

// Los dos datos que el resumen por categoria se comia y que son justo los que
// hacen que alguien abra el hilo. Solo se muestran si hay algo que mostrar:
// el sueldo lo publica ~1 de cada 10 avisos.
const remotas = items.filter(esRemota).length;
const conSueldo = items.filter(p => String(p.sueldo || '').trim()).length;
const stats = [];
if (remotas) stats.push(`🌎 ${remotas} remota${esUno || remotas === 1 ? '' : 's'}`);
if (conSueldo) stats.push(`💰 ${conSueldo} con sueldo`);
if (stats.length) msg += `${stats.join(' · ')}\n`;

// Slack autolinkea el dominio suelto, pero sin utm y sin https explicito.
msg += azar(cierres).replace('pegas.devschile.cl',
  () => `<${SITIO}${utm('cierre')}|pegas.devschile.cl>`);

// Dentro de cada categoria, lo mas nuevo primero: la query trae ORDER BY
// fecha_creacion ASC porque el resto del pipeline la necesita asi.
const porCategoria = new Map(filas.map(([cat]) => [cat, []]));
for (const p of items) porCategoria.get(p.categoria || 'Otros').push(p);
for (const lista of porCategoria.values()) lista.reverse();

// El encabezado de cada categoria lleva al listado ya filtrado del sitio:
// quien mira el hilo por una categoria puntual llega a esa vista y no al home.
const secciones = filas.map(([cat]) => {
  const encabezado = `<${SITIO}/categoria/${slugify(cat)}${utm('categoria')}|${escapar(cat)}>`;
  return `*${encabezado}*\n${porCategoria.get(cat).map(lineaDe).join('\n')}`;
});

// Slack recomienda no pasar los 4000 caracteres por mensaje, y el backlog del
// 27/8 fueron 109 pegas de una sola vez: el detalle se parte en varias
// respuestas del hilo en vez de perderse por el corte. Ojo que la mayor parte
// del presupuesto se la llevan las urls, que no se ven.
const LIMITE = 3800;
const hilo = [];
let bloque = '';
for (const seccion of secciones) {
  if (bloque && bloque.length + seccion.length + 2 > LIMITE) {
    hilo.push(bloque);
    bloque = '';
  }
  bloque = bloque ? `${bloque}\n\n${seccion}` : seccion;
  // Una sola categoria puede pasarse del limite ella sola; ahi se corta entre
  // lineas, nunca a mitad de una.
  while (bloque.length > LIMITE) {
    const corte = bloque.lastIndexOf('\n', LIMITE);
    if (corte <= 0) break;
    hilo.push(bloque.slice(0, corte));
    bloque = bloque.slice(corte + 1);
  }
}
if (bloque) hilo.push(bloque);

const ids = items.map(p => p.id);
return [{ json: { text: msg, hilo, count: total, ids } }];

// Normaliza jobs de WorkingNomads (API publica /api/exposed_jobs/, sin auth)
// al esquema de "pegas". El filtro location=latin-america,chile ya lo aplica
// la API del lado del servidor, asi que aca solo mapeamos campos.
//
// OJO: la API devuelve un array JSON top-level, y el nodo HTTP Request de
// n8n separa automaticamente cada elemento en un item distinto -- item.json
// YA ES un job individual, no un array de jobs. (Bug real detectado en
// produccion: con Array.isArray(item.json) siempre daba false, así que esta
// fuente nunca insertó nada desde que se agregó.)
const items = $input.all();

function categorizar(t) {
  t = (t || '').toLowerCase();

  // 0. Guarda de avisos que no son de TI. Va PRIMERO porque varios de estos
  // títulos traen palabras que más abajo son señal fuerte de otra cosa:
  // "Social Media & Community *Analyst*" caía en Data y "*Community Manager*"
  // caería en Liderazgo. Lista corta y explícita a propósito — acá un falso
  // positivo saca del listado una pega que sí era válida.
  if (/\bcontent (reviewer|creator|writer)\b|\besl\b|\bteacher\b|\bprofesor|\btutor(ing|ía)?\b|\bredactor|\bcopywriter\b|\bcommunity (manager|analyst)\b|\bsocial media\b|\bappointment setting?\b|\bvideo editor\b|\bshort-form video\b|\bcoletor de dados\b|\bphoto collection\b|\bdeduplication collection\b/i.test(t)) return 'Otros';

  // 1-4. Stack explícito en el título: la señal más confiable que hay, así que
  // va antes que cualquier rol. Se conservan tal cual venían de producción,
  // incluido que \breact\b gane antes que Mobile en "React Native" (cambiarlo
  // movería pegas que hoy están clasificadas como Frontend).
  if (/\bfront.?end\b|frontend|\breact\b|\bvue\b|\bangular\b|\bui.ux\b|\bcss\b|\bhtml\b|\btypescript\b|\bjavascript\b|\bjs\b/i.test(t)) return 'Frontend';

  // Backend ampliado con lenguajes y runtimes de servidor que no estaban y por
  // eso caían en Otros (COBOL/mainframe, Elixir/Phoenix, Scala, C++...).
  // Ojo: acá NO van las plataformas de ecosistema (Shopify, Salesforce, SAP,
  // ServiceNow, Oracle...) — esas tienen su propia regla más abajo, a Otros.
  if (/\bback.?end\b|backend|\bnode\b|\bpython\b|\bdjango\b|\bflask\b|\bfastapi\b|\bgo\b|\bgolang\b|\brust\b|\bjava\b|\bspring\b|\bquarkus\b|\.net\b|\bc#\b|\bc\+\+|\bphp\b|\blaravel\b|\bsymfony\b|\brails\b|\bruby\b|\bnestjs\b|\bcobol\b|\bmainframe\b|\bas.?400\b|\bscala\b|\belixir\b|\bphoenix\b|\berlang\b|\bclojure\b|\bperl\b|\bdelphi\b|\brest api(s)?\b|\bapi(s)? rest\b|\bmicroservici/i.test(t)) return 'Backend';

  if (/\bfull.?stack\b|fullstack/i.test(t)) return 'Full Stack';

  // \binfra\b no matcheaba "Infraestructura" ni "Infrastructure" (no hay borde
  // de palabra dentro de la palabra), así que esos avisos dependían de que la
  // fuente trajera categoría propia y si no se iban a Otros.
  if (/\bdevops\b|\bsre\b|\binfra(estructura|structure)?\b|\bcloud\b|\baws\b|\bazure\b|\bgcp\b|\bkubernetes\b|\bdocker\b|\bterraform\b|\bdeploy(ment)?\b|\bsys.?admin\b/i.test(t)) return 'DevOps';

  // 5. QA. Va antes de AI y de Data/BI —como ya hacían 4 de las 5 copias— para
  // que "Analista QA Funcional" sea QA y no Data por la palabra "analista", y
  // que "Senior QA Engineer (AI Platform Systems)" sea QA y no AI. La excepción
  // por \bdata\b es para el caso inverso: "Data Quality Analyst" es Data/BI,
  // el "quality" ahí califica al dato, no al rol.
  if (/\bqa\b|\bsdet\b|\btester\b|\btesting\b|\bcalidad\b|\bquality\b/i.test(t) && !/\bdata\b/i.test(t)) return 'QA';

  // 6. Soporte. Antes de Data/BI por el mismo motivo que QA: "Analista de
  // Soporte Técnico" y "Analista de Soporte y Monitoreo (NOC)" caían en Data
  // por la palabra "analista". Además, esta regla solo existía en la copia de
  // LinkedIn — las otras cuatro fuentes no podían producir la categoría nunca,
  // y de ahí que "Soporte" tuviera 1 sola pega con 945 publicadas.
  if (/\bsoporte\b|\bsupport\b|\bhelp.?desk\b|\bservice.?desk\b|\bmesa de ayuda\b|\bnoc\b/i.test(t)) return 'Soporte';

  // 6. IA/ML/LLM. Categoría nueva: estos términos vivían dentro de la regla de
  // Data y se llevaban 72 de sus 194 pegas ("AI Engineer", "AI Automation
  // Engineer", "Forward Deployed AI Engineer"), que no son ingeniería de datos.
  // Va antes de Data/BI pero después del stack explícito, para que un
  // "Python ML Engineer" siga siendo Backend igual que hoy.
  if (/\bia\b|\ba\.?i\.?\b|\bml\b|\bmlops\b|\bllm(s)?\b|\bgen.?ai\b|\bnlp\b|\bmachine.?learning\b|\bdeep.?learning\b|\bcomputer vision\b|\binteligencia artificial\b|\bartificial intelligence\b|\bprompt engineer/i.test(t)) return 'AI/ML';

  // 7. Data/BI (antes "Data"). Sin los términos de IA, que subieron a la regla
  // anterior, y con \bbi\b agregado: solo estaba \bpower.bi\b, así que
  // "Senior BI Developer (Tableau)" no matcheaba por "BI".
  if (/\bdata\b|\bdatos\b|\banalis(ta|tas)\b|\banalyst(s)?\b|\banalytics\b|\betl\b|\belt\b|\bbi\b|\bpower.?bi\b|\btableau\b|\blooker\b|\bqlik\b|\bwarehouse\b|\bdbt\b|\bspark\b|\bsnowflake\b|\bdatabricks\b/i.test(t)) return 'Data/BI';

  if (/\bmobile\b|\bm[oó]vil(es)?\b|\bandroid\b|\bios\b|\bswift\b|\bkotlin\b|\bflutter\b|\breact.native\b/i.test(t)) return 'Mobile';

  // \bsecurity\b no matcheaba "cybersecurity" por el mismo motivo que \binfra\b:
  // "Cybersecurity Lead" terminaba en Liderazgo y "Senior Cybersecurity
  // Specialist" en Otros.
  if (/\bsecurity\b|\bcyber|\bciber|\bseguridad\b|\bpentest|\bethical hack|\bdevsecops\b|\binfosec\b|\bappsec\b|\bsoc\b/i.test(t)) return 'Ciberseguridad';

  // 8. Diseño va ANTES de Liderazgo: "Líder UX/UI", "UX Design Lead" y
  // "UX Design Manager" son pegas de diseño con un modificador de rol, no
  // pegas de liderazgo. (La copia de LinkedIn las mandaba a Gestión.)
  if (/\bdiseñ|\bdesign(er)?\b|\bart director\b|\bux\b|\bui\b|\bfigma\b|\bsketch\b|\bphotoshop\b|\billustrator\b/i.test(t)) return 'Diseño';

  // 9. Liderazgo (antes "Gestión"), ampliada con arquitecto/CTO/subgerente/VP,
  // que caían en Otros. Va después del stack, de Data/BI y de Diseño a
  // propósito: un "Arquitecto de Datos" o un "Engineering Manager, Data" siguen
  // siendo pegas de datos — el liderazgo es el modificador, no el eje.
  if (/\bproject.manager\b|\bscrum.master\b|\bproduct.manager\b|\bproduct.owner\b|\bagile\b|\bjefe\b|\bgerente\b|\bsub.?gerente\b|\bl[ií]der\b|\blead\b|\btech.?lead\b|\bmanager\b|\bdirector\b|\bcoordinador\b|\barquitect|\barchitect\b|\bcto\b|\bcio\b|\bciso\b|\bhead of\b|\bvp\b|\bvicepresident/i.test(t)) return 'Liderazgo';

  // 11. Plataformas de ecosistema. Van ANTES de la regla de dev genérico
  // porque si no "Shopify Developer" o "Consultor/a SAP" se colarían a
  // Full Stack por la palabra "developer"/"desarrollador".
