// Aviso de un fallo aislado en un paso de ingestion/digest. Estos nodos
// tienen onError=continueErrorOutput: un fallo aca NO frena el resto del
// workflow, esa rama simplemente aporta 0 items. Este es el aviso de que
// igual paso, para no depender de mirar los logs.
const item = $input.first();
const nodo = $prevNode ? $prevNode.name : 'desconocido';
const detalle = (item && item.json && (item.json.error || item.json.message)) || 'sin detalle';
let msg = ':warning: *Un paso de la ingestión falló* (el resto siguió corriendo)\n\n';
msg += '```\n';
msg += `Nodo    ${nodo}\n`;
msg += `Error   ${String(detalle).slice(0, 220)}\n`;
msg += '```';
return [{ json: { text: msg } }];

