// Bug real de la API: en ~50% de los avisos de una muestra, "companyName"
// viene literalmente como el string "name" (placeholder roto del lado de
// Himalayas), en vez del nombre real o venir vacio. "companySlug" si trae
// el dato correcto en esos casos, asi que se arma un nombre legible desde
// ahi como fallback.
function nombreEmpresa(j) {
  if (j.companyName && j.companyName !== 'name') return j.companyName;
  if (j.companySlug) {
    return j.companySlug.split('-').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
  }
  return null;
}

const output = [];
for (const item of items) {
  const jobs = (item.json && item.json.jobs) || [];
  for (const j of jobs) {
    const restricciones = j.locationRestrictions || [];
    const chile = restricciones.includes('Chile');
    const latam = chile || restricciones.some(r => LATAM.includes(r));
    const abierto = restricciones.length === 0;
    if (!latam && !abierto) continue;

    const titulo = j.title || '';
    const url = j.applicationLink || j.guid;
    if (!titulo || !url) continue;

    const ubicacion = chile ? 'Chile' : 'Remoto';
    const sueldo = (j.minSalary && j.maxSalary)
      ? `USD ${j.minSalary} - ${j.maxSalary} /${j.salaryPeriod === 'monthly' ? 'mes' : 'año'}`
      : null;

    output.push({
      json: {
        titulo,
        url,
        empleador: nombreEmpresa(j) || 'No especificado',
        ubicacion,
        categoria: categorizar(titulo),
        sueldo,
        tags: 'remote',
        descripcion: `${titulo}, ${ubicacion}`,
        fuente: 'himalayas',
        email_origen: null,
        fecha_publicacion: j.pubDate ? new Date(j.pubDate * 1000).toISOString() : new Date().toISOString()
      }
    });
  }
