// para responder en el hilo del aviso recién publicado.
//
// El ts del mensaje padre solo existe después de que Slack contesta, por eso
// este nodo va detrás del nodo de Slack y no dentro de "Agrupar
// notificación". Según versión del nodo y tipo de credencial la respuesta
// trae el ts en la raíz o dentro de message, así que se prueban las dos.
const respuesta = $input.first()?.json || {};
const thread_ts = respuesta.ts || respuesta.message?.ts;

// Sin ts no hay hilo al cual colgarse. Se prefiere no publicar nada antes que
// soltar el detalle como mensaje suelto en el canal: eso sería exactamente el
// muro de texto que este cambio evita. El resumen ya salió y las pegas ya
// quedaron marcadas como notificadas, así que no se repite en la próxima.
if (!thread_ts) return [];

const bloques = $('Agrupar notificación').first().json.hilo || [];
return bloques.map(text => ({ json: { text, thread_ts } }));
